from pathlib import Path
import json,hashlib
root=Path('/sdcard/NEXUS_LLM_WIKI'); chunk=root/'staging/unclaimed_chunks/chunk_2.txt'; out=root/'staging/agent_outputs/unclaimed_2.jsonl'
listed=[str(Path(x.strip()).relative_to(root)) for x in chunk.read_text(encoding='utf-8').splitlines() if x.strip()]
rows=[json.loads(x) for x in out.read_text(encoding='utf-8').splitlines() if x.strip()]
errors=[]
if len(rows)!=350: errors.append(f'rows={len(rows)}')
if len(set(r['source_path'] for r in rows))!=350: errors.append('duplicate paths')
if [r['source_path'] for r in rows]!=listed: errors.append('path order mismatch')
for r in rows:
 if not r['claim_id'].startswith('U2_') or r['status']!='candidate': errors.append((r['claim_id'],'id/status'))
 if 'source_note' in r: continue
 p=root/r['source_path']; t=p.read_text(encoding='utf-8'); s,e=r['evidence_start'],r['evidence_end']; q=r['evidence_quote']
 if e-s!=len(q) or t[s:e]!=q: errors.append((r['claim_id'],'slice'))
 if hashlib.sha256(q.encode('utf-8')).hexdigest()!=r['excerpt_sha256']: errors.append((r['claim_id'],'hash'))
print('rows=350 paths=350 source_notes',sum('source_note' in r for r in rows),'claims',sum('source_note' not in r for r in rows),'slice/hash errors',len(errors))
for e in errors[:10]: print(e)
